#include <Arduino.h>
#include <Wire.h>
constexpr uint8_t SDA_PIN=11, SCL_PIN=12, BME280_ADDR=0x77;
void setup(){ Serial.begin(115200); Wire.begin(SDA_PIN,SCL_PIN,100000); Wire.beginTransmission(BME280_ADDR); Wire.write(0xD0); if(Wire.endTransmission(false)==0 && Wire.requestFrom(BME280_ADDR,1)==1) Serial.printf("NANO_ESP32_BME280_ID=0x%02X\n",Wire.read()); else Serial.println("NANO_ESP32_BME280_I2C_ERROR"); }
void loop(){}
